(()=>{'use strict';
 const $=id=>document.getElementById(id),labId=new URLSearchParams(location.search).get('lab')||'',validLab=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(labId);
 const errors={invalid_mobile:'شماره موبایل معتبر وارد کنید.',mobile_not_found:'حساب فعالی با این شماره پیدا نشد.',invalid_otp:'کد تأیید صحیح نیست.',otp_expired:'کد منقضی شده؛ کد جدید بگیرید.',otp_attempts_exceeded:'تعداد تلاش ناموفق زیاد شده؛ کد جدید بگیرید.',otp_rate_limited:'تعداد درخواست زیاد است؛ چند دقیقه دیگر تلاش کنید.',reset_invalid:'تأیید شما منقضی یا استفاده شده؛ کد جدید بگیرید.',lab_manager_required:'این شماره، مدیر فعال لابراتوارِ این لینک نیست.',existing_account_invalid:'وضعیت شمارهٔ حساب تغییر کرده؛ دوباره تأیید کنید.',security_confirmation_required:'لینک لابراتوار و تأیید قطع دسترسی لازم است.',sms_not_configured:'ارسال پیامک فعلاً در دسترس نیست.',sms_send_failed:'پیامک ارسال نشد؛ دوباره تلاش کنید.'};
 let challengeId=null,resetToken=null,busy=false;
 const request=async(url,body)=>{const response=await fetch(url,{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(errors[data.error]||'عملیات انجام نشد؛ دوباره تلاش کنید.');return data};
 async function run(work){if(busy)return;busy=true;$('error').textContent='';document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await work()}catch(e){$('error').textContent=e.message||'ارتباط برقرار نشد.'}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false)}}
 function clearSecrets(){challengeId=resetToken=null;$('password').value=$('confirmPassword').value=$('code').value='';$('disableConfirmation').checked=false;}
 $('restart').onclick=()=>{if(busy)return;clearSecrets();$('verifyForm').hidden=false;$('actions').hidden=true;$('mobile').readOnly=false;$('codeRow').hidden=true;$('code').required=false;$('verifyButton').textContent='دریافت کد تأیید';$('restart').hidden=true;$('error').textContent=$('status').textContent='';};
 $('verifyForm').onsubmit=e=>{e.preventDefault();run(async()=>{if(!challengeId){const data=await request('/api/auth/password-reset/request',{portal:'account',mobile:$('mobile').value});challengeId=data.challengeId;if(!challengeId)throw Error('درخواست تأیید نشد.');$('mobile').readOnly=true;$('codeRow').hidden=false;$('code').required=true;$('verifyButton').textContent='تأیید شماره';$('restart').hidden=false;$('status').textContent='کد پیامکی تا ۵ دقیقه معتبر است.';$('code').focus();}else{const data=await request('/api/auth/password-reset/verify',{challengeId,code:$('code').value});resetToken=data.resetToken;if(!resetToken)throw Error('تأیید انجام نشد.');$('verifyForm').hidden=true;$('actions').hidden=false;$('status').textContent='شماره تأیید شد. یکی از دو اقدام را انتخاب کنید.';}})};
 function done(message){clearSecrets();$('restart').hidden=true;$('actions').hidden=$('verifyForm').hidden=true;$('status').textContent=message;$('recovery').hidden=false;}
 $('changeForm').onsubmit=e=>{e.preventDefault();run(async()=>{if(!resetToken)throw Error('ابتدا شماره را تأیید کنید.');if($('password').value!==$('confirmPassword').value)throw Error('تکرار رمز یکسان نیست.');await request('/api/auth/password-reset/complete',{challengeId,resetToken,newPassword:$('password').value,confirmPassword:$('confirmPassword').value});done('رمز مشترک تغییر کرد و نشست‌های قبلی بسته شدند. با رمز جدید وارد شوید.');})};
 $('disableForm').onsubmit=e=>{e.preventDefault();run(async()=>{if(!validLab||!resetToken||!$('disableConfirmation').checked)throw Error('لینک معتبر، تأیید پیامکی و تأیید قطع دسترسی لازم است.');await request('/api/auth/lab-login-security/disable-password',{labId,challengeId,resetToken,confirm:true});done('رمز فعلی غیرفعال و نشست‌ها بسته شدند. برای ورود دوباره، از بازیابی پیامکی رمز تازه بسازید.');})};
 if(!validLab){$('disableForm').hidden=true;$('error').textContent='این لینک لابراتوار معتبر نیست. می‌توانید رمز حساب خود را با تأیید پیامکی تغییر دهید.';}
 addEventListener('pagehide',clearSecrets);
})();
